var a=`1114-tukir`;var n=`world-1114`;var t=`TL`;var s=`southeast-asia`;var r=4;var o=105;var l={en:`Tukir`,ua:`Тукір`};var h={en:`Tukir is a dish from Timor-Leste prepared with chicken thigh, garlic, lime juice, banana leaf. This is a home-scale version with measured ingredients in the individual steps where they are used. Traditional tukir is cooked inside bamboo; this uses banana-leaf parcels in the oven instead.`,ua:`Тукір, страва кухні країни Тимор-Лешті, яку готують із таких продуктів: куряче стегно, часник, сік лайма, банановий лист. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Традиційний тукір готують у бамбуку; тут згортки з бананового листя запікають у духовці.`};var c=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`chicken-thigh`,780,`g`],[`garlic`,4,`clove`],[`lime-juice`,40,`ml`],[`table-salt`,6,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:12,i:[[`banana-leaf`,7,`leaf`]]},{en:`Put the marinated chicken in clean food-safe banana-leaf parcels and roast them on a baking tray until the meat reaches 74°C; this replaces bamboo cooking.`,ua:`Загорніть замариновану курку в чисте харчове бананове листя та запікайте на деку до 74°C усередині; це заміна готуванню в бамбуку.`,t:[`roasting`],m:45,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`tomato`,170,`g`],[`serrano-pepper`,1,`pcs`]]}];var d={slug:a,id:n,country:`TL`,region:s,servings:4,minutes:105,title:l,text:h,steps:c};export{t as country,d as default,n as id,o as minutes,s as region,r as servings,a as slug,c as steps,h as text,l as title};